{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — Integrative Holistic Care</title>
  <meta name="description" content="Practical whole-person medicine: personalized plans, VIP Day deep dives, functional insight, and ongoing support." />
  <link rel="stylesheet" href="/assets/css/styles.css" />
</head>
<body class="clinic-modern">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="primary-nav" id="mainNav">
        <a href="/services.html">Services</a>
        <a href="/approach.html">How We Work</a>
        <a href="/conditions.html">Concerns</a>
        <a href="/pricing.html">Invest</a>
        <a href="/about.html">About</a>
        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
      <button id="navToggle" class="nav-toggle" aria-label="Menu">☰</button>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero" role="banner">
      <div class="hero-pattern" aria-hidden="true"></div>
      <div class="wrap hero-inner">
        <div class="hero-copy">
          <h1>Whole-person care that fits your life</h1>
          <p class="lead">Practical, evidence-informed integrative medicine that helps you reduce symptoms, support resilience, and craft a sustainable plan — without promises of cures.</p>
          <div class="hero-actions">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="/book.html">Schedule a consult</a>
          </div>
          <p class="muted">Virtual & in-person in {{CITY}}, {{STATE}} • Call <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
        </div>
        <aside class="hero-card">
          <div class="card-inner">
            <h3>VIP Day option</h3>
            <p>Deep-dive assessment, focused treatment plan, and follow-up strategy. Ideal for busy people wanting a concentrated, practical reset.</p>
            <a href="/pricing.html#vip" class="btn small">Learn about VIP Day</a>
            <p class="tiny muter">Clinical recommendations are educational and individualized. Results vary.</p>
          </div>
        </aside>
      </div>
    </section>

    <!-- STORY -->
    <section class="story wrap">
      <div class="story-grid">
        <div>
          <h2>Why a whole-person approach?</h2>
          <p>Traditional symptom-only care can miss drivers like stress, sleep, nutrition, and environment. We blend conventional diagnostics with lifestyle, mind-body tools, and targeted testing when helpful — so your plan addresses root contributors, not just quick fixes.</p>
        </div>
        <div>
          <h3>Meet your practitioner</h3>
          <p>{{PRACTITIONER_NAME}}, {{CREDENTIALS}}, combines clinical training with a practical coaching style to create plans you can actually follow. Learn more on the About page.</p>
          <a href="/about.html" class="link">Read the approach</a>
        </div>
      </div>
    </section>

    <!-- FRAMEWORK -->
    <section class="framework">
      <div class="wrap">
        <h2>Our practical framework</h2>
        <div class="steps">
          <article>
            <svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="10"/></svg>
            <h4>Intake & listening</h4>
            <p>A thorough history to understand patterns, priorities, and what’s already been tried.</p>
          </article>
          <article>
            <svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="4" width="16" height="16" rx="2"/></svg>
            <h4>Targeted assessment</h4>
            <p>Focused labs or screenings when they will change care — explained clearly so you can decide.</p>
          </article>
          <article>
            <svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12h16"/></svg>
            <h4>Action plan</h4>
            <p>Personalized steps that fit your schedule: diet, sleep, activity, stress tools, supplements if appropriate.</p>
          </article>
          <article>
            <svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 4v16"/></svg>
            <h4>Follow-up & adaptation</h4>
            <p>Regular check-ins to measure progress and tweak what’s not working — no one-size-fits-all promises.</p>
          </article>
        </div>
      </div>
    </section>

    <!-- OFFERS -->
    <section class="offers wrap">
      <h2>How we work together</h2>
      <div class="offer-grid">
        <div class="offer">
          <h3>Initial Consult</h3>
          <p>Comprehensive 60–75 minute intake, clinical recommendations, and a clear next-step summary. Good first step for most concerns.</p>
          <a href="/book.html" class="btn">Book an intake</a>
        </div>
        <div class="offer featured">
          <h3>VIP Day — focused deep-dive</h3>
          <p>An intensive, half- or full-day session designed to rapidly create a detailed plan. Includes pre-visit prep and follow-up plan. Great for busy professionals or complex cases.</p>
          <a href="/pricing.html#vip" class="btn primary">Reserve a VIP Day</a>
        </div>
        <div class="offer">
          <h3>Follow-up Care</h3>
          <p>Shorter visits for progress checks, lab reviews, and plan adjustments. Flexible scheduling and a practical, measurable focus.</p>
          <a href="/services.html" class="btn ghost">See follow-ups</a>
        </div>
      </div>
    </section>

    <!-- PRICING SUMMARY -->
    <section class="pricing wrap" id="pricing-summary">
      <h2>Pricing snapshot</h2>
      <div class="pricing-grid">
        <div class="price-card">
          <h4>Initial Visit</h4>
          <div class="price">$250–$350</div>
          <p class="muted">Depending on length and complexity. Includes plan summary.</p>
        </div>
        <div class="price-card">
          <h4>VIP Day</h4>
          <div class="price">From $1,200</div>
          <p class="muted">Includes pre-work, day session, and post-visit summary with next steps.</p>
          <a href="/pricing.html#vip" class="link">Details & availability</a>
        </div>
        <div class="price-card">
          <h4>Follow-up</h4>
          <div class="price">$90–$150</div>
          <p class="muted">Short targeted visits to keep momentum.</p>
        </div>
      </div>
      <p class="tiny">Insurance may apply for some services; contact <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> for billing questions.</p>
    </section>

    <!-- TESTIMONIALS -->
    <section class="testimonials wrap">
      <h2>Patient stories</h2>
      <div class="test-grid">
        <blockquote>
          "I finally have a plan that fits my schedule and actually reduced my anxiety. The focus was on practical changes I could sustain."
          <cite>— S.M., local client</cite>
        </blockquote>
        <blockquote>
          "The VIP Day was transformative — clear steps, lab insights, and a follow-up plan we implemented right away. No hype, just helpful tools."
          <cite>— R.T., executive</cite>
        </blockquote>
      </div>
      <p class="muted tiny">Individual results vary. Care is individualized and educational, not guaranteed.</p>
    </section>

    <!-- CTA -->
    <section class="cta wrap">
      <div class="cta-box">
        <h3>Ready to take a practical step?</h3>
        <p>Schedule a consult or ask about a VIP Day to create a targeted, manageable care plan.</p>
        <div>
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="/contact.html">Questions? Get in touch</a>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p>{{CITY}}, {{STATE}} • <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
      <nav class="footer-nav">
        <a href="/about.html">Who we are</a>
        <a href="/services.html">Services</a>
        <a href="/contact.html">Contact</a>
        <a href="/sitemap.xml">Sitemap</a>
      </nav>
    </div>
  </footer>

  <script src="/assets/js/main.js"></script>
</body>
</html>"} 
