{"path":"assets/css/styles.css","content":"/* Clinic modern stylesheet — self-contained visuals, gradients, SVG pattern background */
:root{--bg:#f6fbf9;--card:#ffffff;--muted:#6b7380;--accent:#1f7a6b;--accent-2:#5cc8b8;--glass:rgba(255,255,255,0.7)}
*{box-sizing:border-box}html,body{height:100%}body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;line-height:1.45;color:#0f1720;background:linear-gradient(180deg,#f8fffc 0%,var(--bg) 100%);}
.wrap{max-width:1080px;margin:0 auto;padding:28px}
.site-header{backdrop-filter:saturate(120%) blur(6px);position:sticky;top:0;background:linear-gradient(180deg,rgba(255,255,255,0.8),rgba(255,255,255,0.6));border-bottom:1px solid rgba(15,23,32,0.05);z-index:40}
.site-header .wrap{display:flex;align-items:center;gap:16px}
.brand{font-weight:700;color:var(--accent);text-decoration:none;font-size:1.1rem}
.primary-nav{margin-left:auto;display:flex;gap:12px;align-items:center}
.primary-nav a{color:#102027;text-decoration:none;padding:8px 10px;border-radius:8px}
.primary-nav a.cta{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:white}
.nav-toggle{display:none;background:none;border:0;font-size:1.3rem;padding:8px}

.hero{display:block;padding:48px 0 28px;position:relative;overflow:hidden}
.hero-pattern{position:absolute;inset:0;background-image:url('/assets/img/pattern.svg');background-repeat:repeat;background-size:320px;opacity:0.12;filter:hue-rotate(10deg) saturate(90%)}
.hero-inner{display:grid;grid-template-columns:1fr 320px;gap:28px;align-items:center;position:relative}
.hero-copy h1{font-size:2rem;margin:0 0 8px}
.lead{margin:0 0 18px;color:var(--muted)}
.hero-actions .btn{margin-right:8px}
.hero-card{background:linear-gradient(180deg,rgba(255,255,255,0.9),var(--card));border:1px solid rgba(15,23,32,0.04);box-shadow:0 6px 22px rgba(16,32,32,0.06);border-radius:12px;padding:18px}
.card-inner h3{margin:0 0 8px}
.tiny{font-size:0.77rem}

.story{padding:28px 0}
.story-grid{display:grid;grid-template-columns:1fr 340px;gap:22px}

.framework{background:linear-gradient(180deg,#ffffff, #f6fffb);padding:28px 0;border-top:1px solid rgba(15,23,32,0.03)}
.framework .steps{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin-top:14px}
.framework article{background:var(--card);padding:18px;border-radius:10px;border:1px solid rgba(15,23,32,0.04);text-align:left}
.icon{width:36px;height:36px;display:block;margin-bottom:8px;fill:var(--accent)}

.offers{padding:26px 0}
.offer-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:18px}
.offer{background:var(--card);padding:18px;border-radius:12px;border:1px solid rgba(15,23,32,0.04)}
.offer.featured{border:2px solid rgba(31,122,107,0.12);box-shadow:0 12px 30px rgba(31,122,107,0.04)}
.btn{display:inline-block;padding:10px 14px;border-radius:8px;text-decoration:none;border:1px solid rgba(15,23,32,0.06);background:transparent;color:var(--accent)}
.btn.small{padding:6px 10px;font-size:0.9rem}
.btn.primary{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:white;border:0}
.btn.ghost{background:transparent;border:1px solid rgba(15,23,32,0.06)}
.link{color:var(--accent);text-decoration:underline}
.muted{color:var(--muted)}

.pricing{padding:24px 0}
.pricing-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.price-card{background:var(--card);padding:16px;border-radius:10px;text-align:center}
.price{font-weight:700;font-size:1.2rem;margin:8px 0}

.testimonials{padding:28px 0}
.test-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}
blockquote{background:linear-gradient(180deg,white,#fbfffc);padding:18px;border-radius:10px;border-left:4px solid var(--accent);}
blockquote cite{display:block;margin-top:10px;color:var(--muted);font-size:0.92rem}

.cta{padding:32px 0}
.cta-box{background:linear-gradient(180deg,#e7fff7,#ffffff);padding:22px;border-radius:12px;border:1px solid rgba(31,122,107,0.06);display:flex;align-items:center;justify-content:space-between;gap:18px}
.cta-box h3{margin:0}

.site-footer{background:linear-gradient(180deg,#ffffff,#f2fbf7);padding:18px 0;border-top:1px solid rgba(15,23,32,0.04)}
.site-footer .wrap{display:flex;justify-content:space-between;align-items:center}
.footer-nav a{margin-left:12px;color:var(--muted);text-decoration:none}

@media (max-width:880px){
  .hero-inner{grid-template-columns:1fr;}
  .story-grid{grid-template-columns:1fr}
  .framework .steps{grid-template-columns:repeat(2,1fr)}
  .offer-grid{grid-template-columns:1fr}
  .pricing-grid{grid-template-columns:1fr}
  .test-grid{grid-template-columns:1fr}
  .nav-toggle{display:block}
  .primary-nav{position:fixed;right:12px;top:64px;background:rgba(255,255,255,0.96);flex-direction:column;padding:12px;border-radius:10px;box-shadow:0 8px 26px rgba(10,20,24,0.06);display:none}
  .primary-nav.show{display:flex}
}

/* Small utility */
.muter{color:#8b949d;font-size:0.78rem}
.tiny{font-size:0.82rem}
"} 
{"path":"assets/js/main.js","content":"// Main JS: lightweight interactions for nav and smooth CTA
(function(){
  var navToggle = document.getElementById('navToggle');
  var mainNav = document.getElementById('mainNav');
  if(navToggle && mainNav){
    navToggle.addEventListener('click', function(){
      mainNav.classList.toggle('show');
      navToggle.setAttribute('aria-expanded', mainNav.classList.contains('show'));
    });
  }

  // Smooth scroll for same-page anchors
  document.addEventListener('click', function(e){
    var t = e.target.closest('a[href^="#"]');
    if(t){
      e.preventDefault();
      var id = t.getAttribute('href').slice(1);
      var el = document.getElementById(id);
      if(el) el.scrollIntoView({behavior:'smooth',block:'start'});
    }
  });

  // Simple accessibility: focus main when skip (if implemented elsewhere)
  window.addEventListener('hashchange', function(){
    var id = location.hash.replace('#','');
    var el = document.getElementById(id);
    if(el) el.setAttribute('tabindex','-1') && el.focus();
  });
})();"} 
